<section class="erp-card erp-supplier-form-card"><div class="erp-section-head"><div><h2><?php p(!empty($s['id'])?'Lieferant bearbeiten':'Lieferant anlegen');?></h2><p class="erp-muted">Stammdaten, Kontakt und Konditionen.</p></div></div><form method="post" action="<?php p($url->linkToRoute('reinhardterp.module.saveSupplierMaster'));?>"><input type="hidden" name="requesttoken" value="<?php p($_['requesttoken']);?>"><?php if(!empty($s['id'])):?><input type="hidden" name="id" value="<?php p($s['id']);?>"><?php endif;?><div class="erp-form-grid erp-supplier-form-grid"><div class="erp-span-2"><label>Firma / Name *</label><input name="name" required value="<?php p($s['name']??'');?>"></div><div><label>Ansprechpartner</label><input name="contactPerson" value="<?php p($s['contact_person']??'');?>"></div><div><label>Kundennummer bei Lieferant</label><input name="customerNo" value="<?php p($s['customer_no']??'');?>"></div><div><label>Straße</label><input name="street" value="<?php p($s['street']??'');?>"></div><div><label>PLZ</label><input name="postalCode" value="<?php p($s['postal_code']??'');?>"></div><div><label>Ort</label><input name="city" value="<?php p($s['city']??'');?>"></div><div><label>Land</label><input name="country" value="<?php p($s['country']??'');?>"></div><div><label>E-Mail</label><input type="email" name="email" value="<?php p($s['email']??'');?>"></div><div><label>Telefon</label><input name="phone" value="<?php p($s['phone']??'');?>"></div><div><label>Website</label><input name="website" value="<?php p($s['website']??'');?>"></div><div><label>Zahlungsziel</label><input name="paymentTerms" value="<?php p($s['payment_terms']??'');?>" placeholder="z. B. 14 Tage 2 %, 30 Tage netto"></div><div><label>IBAN</label><input name="iban" value="<?php p($s['iban']??'');?>"></div><div><label>BIC</label><input name="bic" value="<?php p($s['bic']??'');?>"></div><div class="erp-span-2"><label>Notizen</label><textarea name="notes" rows="4"><?php p($s['notes']??'');?></text